ranslations":["simpático","simpática","amigable"],"ipa":"/ˈfrɛndli/","romanization":null,"emoji":null,"example_en":"Our teacher is very friendly.","example_es":"Nuestra profesora es muy simpática.","difficulty":1,"tags":["personality"]},{"id":"en-kind","language_code":"en","unit_id":"a2-u15","text":"kind","translation_es":"amable","accepted_translations":[],"ipa":"/kaɪnd/","romanization":null,"emoji":null,"example_en":"My grandmother is very kind.","example_es":"Mi abuela es muy amable.","difficulty":1,"tags":["personality"]},{"id":"en-funny","language_code":"en","unit_id":"a2-u15","text":"funny","translation_es":"gracioso / graciosa","accepted_translations":["gracioso","graciosa","chistoso","chistosa"],"ipa":"/ˈfʌni/","romanization":null,"emoji":"😄","example_en":"My brother is very funny.","example_es":"Mi hermano es muy gracioso.","difficulty":1,"tags":["personality"]},{"id":"en-shy","language_code":"en","unit_id":"a2-u15","text":"shy","translation_es":"tímido / tímida","accepted_translations":["tímido","tímida"],"ipa":"/ʃaɪ/","romanization":null,"emoji":"🙈","example_en":"He's shy, but he's very nice.","example_es":"Es tímido, pero es muy buena persona.","difficulty":1,"tags":["personality"]},{"id":"en-quiet","language_code":"en","unit_id":"a2-u15","text":"quiet","translation_es":"tranquilo / silencioso","accepted_translations":["tranquilo","tranquila","silencioso","silenciosa","callado","callada"],"ipa":"/ˈkwaɪət/","romanization":null,"emoji":"🤫","example_en":"I live in a quiet street.","example_es":"Vivo en una calle tranquila.","difficulty":1,"tags":["places","personality"]},{"id":"en-noisy","language_code":"en","unit_id":"a2-u15","text":"noisy","translation_es":"ruidoso / ruidosa","accepted_translations":["ruidoso","ruidosa"],"ipa":"/ˈnɔɪzi/","romanization":null,"emoji":"🔊","example_en":"The city is very noisy.","example_es":"La ciudad es muy ruidosa.","difficulty":1,"tags":["places"]},{"id":"en-crowded","language_code":"en","unit_id":"a2-u15","text":"crowded","translation_es":"lleno de gente","accepted_translations":["llena de gente","repleto","repleta"],"ipa":"/ˈkraʊdəd/","romanization":null,"emoji":null,"example_en":"The beach is very crowded in summer.","example_es":"En verano la playa está llena de gente.","difficulty":1,"tags":["places"]},{"id":"en-modern","language_code":"en","unit_id":"a2-u15","text":"modern","translation_es":"moderno / moderna","accepted_translations":["moderno","moderna"],"ipa":"/ˈmɑdərn/","romanization":null,"emoji":null,"example_en":"They live in a modern house.","example_es":"Viven en una casa moderna.","difficulty":1,"tags":["places"]},{"id":"en-dirty","language_code":"en","unit_id":"a2-u15","text":"dirty","translation_es":"sucio / sucia","accepted_translations":["sucio","sucia"],"ipa":"/ˈdɜrti/","romanization":null,"emoji":null,"example_en":"The street is dirty.","example_es":"La calle está sucia.","difficulty":1,"tags":["places"]},{"id":"en-neighborhood","language_code":"en","unit_id":"a2-u15","text":"neighborhood","translation_es":"barrio","accepted_translations":[],"ipa":"/ˈneɪbərˌhʊd/","romanization":null,"emoji":"🏘️","example_en":"My neighborhood is quiet.","example_es":"Mi barrio es tranquilo.","difficulty":1,"tags":["places"]},{"id":"en-message","language_code":"en","unit_id":"a2-u16","text":"message","translation_es":"mensaje","accepted_translations":[],"ipa":"/ˈmɛsɪdʒ/","romanization":null,"emoji":"💬","example_en":"I got your message.","example_es":"Recibí tu mensaje.","difficulty":1,"tags":["messages"]},{"id":"en-dear","language_code":"en","unit_id":"a2-u16","text":"dear","translation_es":"querido / querida (en cartas)","accepted_translations":["querido","querida","estimado","estimada"],"ipa":"/dɪr/","romanization":null,"emoji":null,"example_en":"Dear Ana, how are you?","example_es":"Querida Ana, ¿cómo estás?","difficulty":1,"tags":["messages"]},{"id":"en-thanks-for","language_code":"en","unit_id":"a2-u16","text":"thanks for","translation_es":"gracias por","accepted_translations":[],"ipa":"/ˈθæŋks fɔr/","romanization":null,"emoji":"🙏","example_en":"Thanks for your message!","example_es":"¡Gracias por tu mensaje!","difficulty":1,"tags":["messages"]},{"id":"en-take-care","language_code":"en","unit_id":"a2-u16","text":"take care","translation_es":"cuidate","accepted_translations":["cuídate","cuídese"],"ipa":"/ˈteɪk ˈkɛr/","romanization":null,"emoji":"👋","example_en":"Take care, Ana!","example_es":"¡Cuidate, Ana!","difficulty":1,"tags":["messages"]},{"id":"en-best-wishes","language_code":"en","unit_id":"a2-u16","text":"best wishes","translation_es":"saludos / cariños (al despedirse)","accepted_translations":["saludos","cariños"],"ipa":"/bɛst ˈwɪʃəz/","romanization":null,"emoji":null,"example_en":"Best wishes, Leo","example_es":"Saludos, Leo","difficulty":1,"tags":["messages"]},{"id":"en-reply","language_code":"en","unit_id":"a2-u16","text":"reply","translation_es":"responder (un mensaje)","accepted_translations":["responder","contestar"],"ipa":"/rɪˈplaɪ/","romanization":null,"emoji":null,"example_en":"Please reply soon.","example_es":"Por favor, respondé pronto.","difficulty":1,"tags":["messages","verbs"]},{"id":"en-send","language_code":"en","unit_id":"a2-u16","text":"send","translation_es":"enviar / mandar","accepted_translations":["enviar","mandar"],"ipa":"/sɛnd/","romanization":null,"emoji":"📤","example_en":"I send a lot of messages.","example_es":"Mando muchos mensajes.","difficulty":1,"tags":["messages","verbs"]},{"id":"en-call-back","language_code":"en","unit_id":"a2-u16","text":"call back","translation_es":"devolver la llamada","accepted_translations":["volver a llamar"],"ipa":"/ˈkɔl ˈbæk/","romanization":null,"emoji":null,"example_en":"Can you call me back?","example_es":"¿Me podés devolver la llamada?","difficulty":1,"tags":["phone"]},{"id":"en-leave-a-message","language_code":"en","unit_id":"a2-u16","text":"leave a message","translation_es":"dejar un mensaje","accepted_translations":[],"ipa":"/liv ə ˈmɛsɪdʒ/","romanization":null,"emoji":null,"example_en":"Can I leave a message?","example_es":"¿Puedo dejar un mensaje?","difficulty":1,"tags":["phone"]},{"id":"en-hold-on","language_code":"en","unit_id":"a2-u16","text":"hold on","translation_es":"un momento (al teléfono)","accepted_translations":["un momento","espere","esperá"],"ipa":"/hoʊld ˈɑn/","romanization":null,"emoji":"☎️","example_en":"Hold on, please.","example_es":"Un momento, por favor.","difficulty":1,"tags":["phone"]},{"id":"en-could-you","language_code":"en","unit_id":"a2-u16","text":"could you","translation_es":"¿podrías…? / ¿podría…?","accepted_translations":["podrías","podría"],"ipa":"/kʊd ju/","romanization":null,"emoji":null,"example_en":"Could you help me, please?","example_es":"¿Podrías ayudarme, por favor?","difficulty":1,"tags":["requests"]},{"id":"en-book-a-room","language_code":"en","unit_id":"a2-u16","text":"book a room","translation_es":"reservar una habitación","accepted_translations":[],"ipa":"/bʊk ə ˈrum/","romanization":null,"emoji":"🛎️","example_en":"I'd like to book a room.","example_es":"Quisiera reservar una habitación.","difficulty":1,"tags":["hotel"]},{"id":"en-double-room","language_code":"en","unit_id":"a2-u16","text":"double room","translation_es":"habitación doble","accepted_translations":[],"ipa":"/ˈdʌbəl ˈrum/","romanization":null,"emoji":"🛏️","example_en":"We want a double room.","example_es":"Queremos una habitación doble.","difficulty":1,"tags":["hotel"]},{"id":"en-check-in","language_code":"en","unit_id":"a2-u16","text":"check in","translation_es":"registrarse (en un hotel)","accepted_translations":["registrarse","hacer el check-in"],"ipa":"/tʃɛk ˈɪn/","romanization":null,"emoji":null,"example_en":"You can check in at two.","example_es":"Pueden registrarse a las dos.","difficulty":1,"tags":["hotel"]},{"id":"en-check-out","language_code":"en","unit_id":"a2-u16","text":"check out","translation_es":"dejar la habitación (en un hotel)","accepted_translations":["dejar la habitación","hacer el check-out"],"ipa":"/tʃɛk ˈaʊt/","romanization":null,"emoji":null,"example_en":"We check out on Sunday.","example_es":"Dejamos la habitación el domingo.","difficulty":1,"tags":["hotel"]},{"id":"en-reception","language_code":"en","unit_id":"a2-u16","text":"reception","translation_es":"recepción","accepted_translations":[],"ipa":"/rɪˈsɛpʃən/","romanization":null,"emoji":null,"example_en":"The key is at reception.","example_es":"La llave está en recepción.","difficulty":1,"tags":["hotel"]},{"id":"en-story","language_code":"en","unit_id":"a2-u17","text":"story","translation_es":"historia / cuento","accepted_translations":["historia","cuento"],"ipa":"/ˈstɔri/","romanization":null,"emoji":"📖","example_en":"I read a story every night.","example_es":"Leo una historia todas las noches.","difficulty":1,"tags":["stories"]},{"id":"en-while","language_code":"en","unit_id":"a2-u17","text":"while","translation_es":"mientras","accepted_translations":[],"ipa":"/waɪl/","romanization":null,"emoji":null,"example_en":"I was cooking while she was reading.","example_es":"Yo cocinaba mientras ella leía.","difficulty":1,"tags":["stories","grammar"]},{"id":"en-suddenly","language_code":"en","unit_id":"a2-u17","text":"suddenly","translation_es":"de repente","accepted_translations":["de pronto"],"ipa":"/ˈsʌdənli/","romanization":null,"emoji":"⚡","example_en":"Suddenly, my phone rang.","example_es":"De repente, sonó mi teléfono.","difficulty":1,"tags":["stories"]},{"id":"en-happened","language_code":"en","unit_id":"a2-u17","text":"happened","translation_es":"pasó / sucedió","accepted_translations":["pasó","sucedió","ocurrió"],"ipa":"/ˈhæpənd/","romanization":null,"emoji":null,"example_en":"What happened?","example_es":"¿Qué pasó?","difficulty":1,"tags":["stories","past"]},{"id":"en-at-first","language_code":"en","unit_id":"a2-u17","text":"at first","translation_es":"al principio","accepted_translations":[],"ipa":"/æt ˈfɜrst/","romanization":null,"emoji":null,"example_en":"At first, I was nervous.","example_es":"Al principio estaba nervioso.","difficulty":1,"tags":["stories"]},{"id":"en-in-the-end","language_code":"en","unit_id":"a2-u17","text":"in the end","translation_es":"al final","accepted_translations":["finalmente"],"ipa":"/ɪn ðə ˈɛnd/","romanization":null,"emoji":null,"example_en":"In the end, we were happy.","example_es":"Al final, estábamos contentos.","difficulty":1,"tags":["stories"]},{"id":"en-the-next-day","language_code":"en","unit_id":"a2-u17","text":"the next day","translation_es":"al día siguiente","accepted_translations":[],"ipa":"/ðə ˈnɛkst ˈdeɪ/","romanization":null,"emoji":null,"example_en":"The next day, we went to the beach.","example_es":"Al día siguiente fuimos a la playa.","difficulty":1,"tags":["stories"]},{"id":"en-fell","language_code":"en","unit_id":"a2-u17","text":"fell","translation_es":"me caí / se cayó (fall)","accepted_translations":["me caí","se cayó","cayó"],"ipa":"/fɛl/","romanization":null,"emoji":null,"example_en":"She fell in the street.","example_es":"Se cayó en la calle.","difficulty":1,"tags":["stories","past"]},{"id":"en-broke","language_code":"en","unit_id":"a2-u17","text":"broke","translation_es":"rompí / rompió (break)","accepted_translations":["rompí","rompió","se rompió"],"ipa":"/broʊk/","romanization":null,"emoji":null,"example_en":"He broke his arm.","example_es":"Se rompió el brazo.","difficulty":1,"tags":["stories","past"]},{"id":"en-rang","language_code":"en","unit_id":"a2-u17","text":"rang","translation_es":"sonó (ring)","accepted_translations":[],"ipa":"/ræŋ/","romanization":null,"emoji":"📞","example_en":"My phone rang at six.","example_es":"Mi teléfono sonó a las seis.","difficulty":1,"tags":["stories","past"]},{"id":"en-began","language_code":"en","unit_id":"a2-u17","text":"began","translation_es":"empecé / empezó (begin)","accepted_translations":["empezó","comenzó"],"ipa":"/bɪˈɡæn/","romanization":null,"emoji":null,"example_en":"It began to rain.","example_es":"Empezó a llover.","difficulty":1,"tags":["stories","past"]},{"id":"en-heard","language_code":"en","unit_id":"a2-u17","text":"heard","translation_es":"oí / oyó (hear)","accepted_translations":["oí","oyó","escuché","escuchó"],"ipa":"/hɜrd/","romanization":null,"emoji":"👂","example_en":"I heard a noise.","example_es":"Oí un ruido.","difficulty":1,"tags":["stories","past"]},{"id":"en-noise","language_code":"en","unit_id":"a2-u17","text":"noise","translation_es":"ruido","accepted_translations":[],"ipa":"/nɔɪz/","romanization":null,"emoji":null,"example_en":"I heard a noise outside.","example_es":"Oí un ruido afuera.","difficulty":1,"tags":["stories"]},{"id":"en-scared","language_code":"en","unit_id":"a2-u17","text":"scared","translation_es":"asustado / asustada","accepted_translations":["asustado","asustada","con miedo"],"ipa":"/skɛrd/","romanization":null,"emoji":"😱","example_en":"I was very scared.","example_es":"Estaba muy asustado.","difficulty":1,"tags":["stories","feelings"]},{"id":"en-luckily","language_code":"en","unit_id":"a2-u17","text":"luckily","translation_es":"por suerte","accepted_translations":["afortunadamente"],"ipa":"/ˈlʌkəli/","romanization":null,"emoji":"🍀","example_en":"Luckily, the doctor was there.","example_es":"Por suerte, el médico estaba ahí.","difficulty":1,"tags":["stories"]},{"id":"en-outside","language_code":"en","unit_id":"a2-u17","text":"outside","translation_es":"afuera","accepted_translations":["fuera"],"ipa":"/ˌaʊtˈsaɪd/","romanization":null,"emoji":null,"example_en":"The children were playing outside.","example_es":"Los chicos estaban jugando afuera.","difficulty":1,"tags":["stories","places"]}],"lessons":[{"id":"a2-u13-l01","unit_id":"a2-u13","position":1,"title_es":"El menú","objective_es":"Nombrar los platos de un menú.","intro":{"explanation":"En un restaurante, el menú (menu) se divide en platos: soup (sopa), salad (ensalada), meat (carne), fish (pescado) y dessert (postre). Vegetables (verduras) casi siempre va en plural.","examples":[{"target":"Can I see the menu, please?","base":"¿Puedo ver el menú, por favor?"},{"target":"I want the fish soup.","base":"Quiero la sopa de pescado."}]},"takeaways":["Nombrás los platos de un menú: soup, salad, meat, fish, dessert.","Pedís ver el menú con Can I see the menu, please?"]},{"id":"a2-u13-l02","unit_id":"a2-u13","position":2,"title_es":"Some y any","objective_es":"Decir qué hay y qué no hay con some y any.","intro":{"explanation":"Some (algo de, unos) va en oraciones afirmativas: There is some milk. Any va en negativas y en preguntas: There isn’t any milk. Is there any milk?","examples":[{"target":"There are some eggs.","base":"Hay unos huevos."},{"target":"We don't have any bread.","base":"No tenemos nada de pan."}]},"takeaways":["Usás some en afirmativas: There is some cheese.","Usás any en negativas y preguntas: Is there any juice?"]},{"id":"a2-u13-rev1","unit_id":"a2-u13","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «El menú» y «Some y any».","intro":null,"takeaways":[]},{"id":"a2-u13-l03","unit_id":"a2-u13","position":4,"title_es":"Pedir la comida","objective_es":"Pedir una mesa y la comida con Could I have…?","intro":{"explanation":"Para pedir con cortesía se usa Could I have…? (¿me podría dar…?). Al llegar se pide la mesa: A table for two, please. Para decir que algo está muy rico: It’s delicious!","examples":[{"target":"A table for two, please.","base":"Una mesa para dos, por favor."},{"target":"Could I have the soup, please?","base":"¿Me podría dar la sopa, por favor?"}]},"takeaways":["Pedís una mesa: A table for two, please.","Pedís con cortesía: Could I have the fish, please?","Decís si la comida está delicious o es spicy."]},{"id":"a2-u13-l04","unit_id":"a2-u13","position":5,"title_es":"Mucho y muchos","objective_es":"Hablar de cantidades con much, many y a lot of.","intro":{"explanation":"Many va con lo que se cuenta (many people, many eggs) y much con lo que no se cuenta (much water, much money), sobre todo en negativas y preguntas. A lot of sirve para los dos, sobre todo en afirmativas.","examples":[{"target":"There aren't many people here.","base":"No hay mucha gente acá."},{"target":"I drink a lot of water.","base":"Tomo mucha agua."}]},"takeaways":["Usás many con lo que se cuenta y much con lo que no.","Usás a lot of en afirmativas: a lot of vegetables."]},{"id":"a2-u13-rev2","unit_id":"a2-u13","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Pedir la comida» y «Mucho y muchos».","intro":null,"takeaways":[]},{"id":"a2-u13-l05","unit_id":"a2-u13","position":7,"title_es":"La cuenta, por favor","objective_es":"Leer un menú con precios, pedir la cuenta y pagar.","intro":{"explanation":"Al final se pide la cuenta (the bill): Could I have the bill, please? Se paga by card (con tarjeta) o in cash (en efectivo).","examples":[{"target":"Could I have the bill, please?","base":"¿Me podría dar la cuenta, por favor?"},{"target":"Can I pay by card?","base":"¿Puedo pagar con tarjeta?"}]},"takeaways":["Leés un menú con precios.","Pedís la cuenta y preguntás cómo pagar."]},{"id":"a2-u13-listen","unit_id":"a2-u13","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"a2-u13-words","unit_id":"a2-u13","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"a2-u13-final","unit_id":"a2-u13","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Comer afuera».","intro":null,"takeaways":[]},{"id":"a2-u14-l01","unit_id":"a2-u14","position":1,"title_es":"Pasatiempos","objective_es":"Contar qué hacés en tu tiempo libre y con qué frecuencia.","intro":{"explanation":"Para hablar de tus pasatiempos (hobbies) usás el presente simple y expresiones de frecuencia: often (a menudo), once a week (una vez por semana), twice a week (dos veces por semana).","examples":[{"target":"My hobby is cooking.","base":"Mi pasatiempo es cocinar."},{"target":"I go to the gym once a week.","base":"Voy al gimnasio una vez por semana."}]},"takeaways":["Contás qué hacés en tu tiempo libre.","Decís con qué frecuencia: often, once a week, twice a week."]},{"id":"a2-u14-l02","unit_id":"a2-u14","position":2,"title_es":"¿Te gustaría venir?","objective_es":"Invitar a alguien y aceptar o rechazar una invitación.","intro":{"explanation":"Para invitar: Would you like to…? (¿te gustaría…?). Para aceptar: I'd love to! (¡me encantaría!). Para rechazar con amabilidad: Sorry, I can't. Maybe another time.","examples":[{"target":"Would you like to go to the cinema?","base":"¿Te gustaría ir al cine?"},{"target":"Sorry, I can't. Maybe another time.","base":"Perdón, no puedo. Quizás otro día."}]},"takeaways":["Invitás con Would you like to…?","Aceptás con I'd love to y rechazás con Sorry, I can't."]},{"id":"a2-u14-rev1","unit_id":"a2-u14","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Pasatiempos» y «¿Te gustaría venir?».","intro":null,"takeaways":[]},{"id":"a2-u14-l03","unit_id":"a2-u14","position":4,"title_es":"Proponer un plan","objective_es":"Proponer planes con Let's… y How about…?","intro":{"explanation":"Para proponer algo: Let's… (¡vamos a…!) o How about…? (¿qué tal si…?). Después de how about va un sustantivo o un verbo con -ing: How about Sunday? How about going out?","examples":[{"target":"Let's go out tonight!","base":"¡Salgamos esta noche!"},{"target":"How about Sunday?","base":"¿Qué tal el domingo?"}]},"takeaways":["Proponés planes con Let's… y How about…?","Decís que hacen algo juntos: together."]},{"id":"a2-u14-l04","unit_id":"a2-u14","position":5,"title_es":"Quedar para verse","objective_es":"Acordar dónde y a qué hora encontrarse.","intro":{"explanation":"Para quedar se dice el lugar y la hora: Let's meet at the station at seven (encontrémonos en la estación a las siete). Para saber si alguien terminó de prepararse: Are you ready? (¿estás listo?).","examples":[{"target":"Let's meet at the station at seven.","base":"Encontrémonos en la estación a las siete."},{"target":"Are you ready?","base":"¿Estás listo?"}]},"takeaways":["Proponés un lugar y una hora para encontrarse.","Preguntás si alguien está listo: Are you ready?"]},{"id":"a2-u14-rev2","unit_id":"a2-u14","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Proponer un plan» y «Quedar para verse».","intro":null,"takeaways":[]},{"id":"a2-u14-l05","unit_id":"a2-u14","position":7,"title_es":"Responder una invitación","objective_es":"Entender una invitación escrita y responderla.","intro":{"explanation":"Una invitación dice qué es, cuándo y dónde. Para responder, agradecé y aceptá o rechazá dando una razón: Thank you! I’d love to go. / Sorry, I can’t. I have to work.","examples":[{"target":"Thank you! I'd love to go.","base":"¡Gracias! Me encantaría ir."},{"target":"Sorry, I can't. I have to work.","base":"Perdón, no puedo. Tengo que trabajar."}]},"takeaways":["Entendés una invitación escrita: qué, cuándo y dónde.","Aceptás o rechazás una invitación dando una razón."]},{"id":"a2-u14-listen","unit_id":"a2-u14","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"a2-u14-words","unit_id":"a2-u14","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"a2-u14-final","unit_id":"a2-u14","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Tiempo libre e invitaciones».","intro":null,"takeaways":[]},{"id":"a2-u15-l01","unit_id":"a2-u15","position":1,"title_es":"¿Cómo es físicamente?","objective_es":"Preguntar y decir cómo es alguien físicamente.","intro":{"explanation":"Para preguntar por el aspecto de alguien: What does he look like? Se responde con be (He is tall and thin) o con have para el pelo, la barba o los anteojos (She has curly hair. He has a beard).","examples":[{"target":"What does she look like?","base":"¿Cómo es (físicamente)?"},{"target":"She has long blond hair.","base":"Tiene el pelo largo y rubio."}]},"takeaways":["Preguntás por el aspecto con What does he look like?","Describís el pelo y la cara con have: She has curly hair."]},{"id":"a2-u15-l02","unit_id":"a2-u15","position":2,"title_es":"¿Cómo es de carácter?","objective_es":"Describir el carácter de una persona.","intro":{"explanation":"What is she like? pregunta por el carácter (¿cómo es como persona?), y What does she look like?, por el aspecto. El carácter se describe con be: She is kind and funny.","examples":[{"target":"What is your teacher like?","base":"¿Cómo es tu profesor?"},{"target":"She's very friendly.","base":"Es muy simpática."}]},"takeaways":["Distinguís What is she like? (carácter) de What does she look like? (aspecto).","Describís el carácter: friendly, kind, funny, shy."]},{"id":"a2-u15-rev1","unit_id":"a2-u15","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «¿Cómo es físicamente?» y «¿Cómo es de carácter?».","intro":null,"takeaways":[]},{"id":"a2-u15-l03","unit_id":"a2-u15","position":4,"title_es":"Mi barrio","objective_es":"Describir un barrio y un lugar.","intro":{"explanation":"Un lugar se describe con be + adjetivo (The street is quiet) o con el adjetivo antes del sustantivo (a quiet street). Con there is y there are contás qué hay en tu barrio (neighborhood).","examples":[{"target":"I live in a quiet neighborhood.","base":"Vivo en un barrio tranquilo."},{"target":"The city is noisy and crowded.","base":"La ciudad es ruidosa y está llena de gente."}]},"takeaways":["Describís un lugar: quiet, noisy, crowded, modern, dirty.","Contás qué hay en tu barrio con there is y there are."]},{"id":"a2-u15-l04","unit_id":"a2-u15","position":5,"title_es":"Comparar personas y lugares","objective_es":"Comparar personas y lugares con los comparativos.","intro":{"explanation":"Con lo que aprendiste en «Comparar» podés comparar personas y lugares. Los adjetivos cortos terminados en -y cambian la y por -ier: noisy → noisier, funny → funnier. Y los cortos con una vocal y una consonante la duplican: thin → thinner.","examples":[{"target":"My brother is thinner than me.","base":"Mi hermano es más flaco que yo."},{"target":"The city is noisier than my neighborhood.","base":"La ciudad es más ruidosa que mi barrio."}]},"takeaways":["Comparás personas: taller than, funnier than.","Comparás lugares: quieter than, the most crowded."]},{"id":"a2-u15-rev2","unit_id":"a2-u15","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Mi barrio» y «Comparar personas y lugares».","intro":null,"takeaways":[]},{"id":"a2-u15-l05","unit_id":"a2-u15","position":7,"title_es":"Describir a alguien","objective_es":"Describir a una persona: aspecto y carácter.","intro":{"explanation":"Para describir a una persona, empezá por el aspecto (He is tall. He has dark hair.) y seguí por el carácter (He is friendly and funny). Uní las ideas con and, but y because.","examples":[{"target":"He has dark hair and he wears glasses.","base":"Tiene el pelo oscuro y usa anteojos."},{"target":"She's shy, but she's very kind.","base":"Es tímida, pero es muy amable."}]},"takeaways":["Describís a una persona: aspecto y carácter.","Unís ideas con and, but y because."]},{"id":"a2-u15-listen","unit_id":"a2-u15","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"a2-u15-words","unit_id":"a2-u15","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"a2-u15-final","unit_id":"a2-u15","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Cómo es».","intro":null,"takeaways":[]},{"id":"a2-u16-l01","unit_id":"a2-u16","position":1,"title_es":"Un mensaje a un amigo","objective_es":"Escribir y entender mensajes cortos entre amigos.","intro":{"explanation":"Un mensaje informal empieza con Hi y el nombre, y termina con See you soon! (¡hasta pronto!) o Take care! (¡cuidate!). Para agradecer: Thanks for… (gracias por…).","examples":[{"target":"Thanks for your message!","base":"¡Gracias por tu mensaje!"},{"target":"See you soon!","base":"¡Hasta pronto!"}]},"takeaways":["Escribís y entendés mensajes cortos entre amigos.","Agradecés con Thanks for… y te despedís con See you soon o Take care."]},{"id":"a2-u16-l02","unit_id":"a2-u16","position":2,"title_es":"Un correo","objective_es":"Empezar y terminar un correo, y pedir algo con Could you…?","intro":{"explanation":"Un correo empieza con Dear + nombre (Dear Leo,) y termina con Best wishes, + tu nombre. Para pedir algo con cortesía: Could you…? (¿podrías…?) + el verbo.","examples":[{"target":"Dear Leo,","base":"Querido Leo:"},{"target":"Could you send me the photos, please?","base":"¿Podrías mandarme las fotos, por favor?"}]},"takeaways":["Empezás un correo con Dear… y lo terminás con Best wishes.","Pedís algo con cortesía: Could you…?"]},{"id":"a2-u16-rev1","unit_id":"a2-u16","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Un mensaje a un amigo» y «Un correo».","intro":null,"takeaways":[]},{"id":"a2-u16-l03","unit_id":"a2-u16","position":4,"title_es":"Al teléfono","objective_es":"Pedir hablar con alguien y dejar un mensaje.","intro":{"explanation":"Al teléfono: Can I speak to…? (¿puedo hablar con…?). Si la persona no está, podés dejar un mensaje (leave a message) o pedir que te devuelva la llamada (call me back). Hold on, please = un momento, por favor.","examples":[{"target":"Can I speak to Emma, please?","base":"¿Puedo hablar con Emma, por favor?"},{"target":"Hold on, please.","base":"Un momento, por favor."}]},"takeaways":["Pedís hablar con alguien y dejás un mensaje.","Entendés Hold on y pedís que te llamen: call me back."]},{"id":"a2-u16-l04","unit_id":"a2-u16","position":5,"title_es":"Reservar un hotel","objective_es":"Reservar una habitación y entender las reglas del hotel.","intro":{"explanation":"Para reservar: I'd like to book a room. Una habitación para dos personas es a double room. Check in es registrarte al llegar y check out, dejar la habitación al irte.","examples":[{"target":"I'd like to book a double room.","base":"Quisiera reservar una habitación doble."},{"target":"You can check in at two.","base":"Pueden registrarse a las dos."}]},"takeaways":["Reservás una habitación de hotel.","Entendés el check in, el check out y la recepción."]},{"id":"a2-u16-rev2","unit_id":"a2-u16","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Al teléfono» y «Reservar un hotel».","intro":null,"takeaways":[]},{"id":"a2-u16-l05","unit_id":"a2-u16","position":7,"title_es":"Responder un correo","objective_es":"Entender un correo y responderlo.","intro":{"explanation":"Para responder un correo: agradecé (Thanks for your email), contestá lo que te preguntan y despedite (Best wishes / See you soon). Si te piden algo, decí qué vas a hacer con will: I’ll send you the photos tonight.","examples":[{"target":"Thanks for your email.","base":"Gracias por tu correo."},{"target":"I'll send you the photos tonight.","base":"Esta noche te mando las fotos."}]},"takeaways":["Respondés un correo: agradecés, contestás y te despedís.","Decís qué vas a hacer con will: I’ll send…"]},{"id":"a2-u16-listen","unit_id":"a2-u16","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"a2-u16-words","unit_id":"a2-u16","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"a2-u16-final","unit_id":"a2-u16","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Mensajes, correos y llamadas».","intro":null,"takeaways":[]},{"id":"a2-u17-l01","unit_id":"a2-u17","position":1,"title_es":"Lo que estaba pasando","objective_es":"Contar qué estaba pasando en un momento del pasado.","intro":{"explanation":"El past continuous cuenta lo que estaba pasando en un momento del pasado: was/were + verbo con -ing. Con I, he, she e it va was; con you, we y they, were.","examples":[{"target":"I was reading at nine.","base":"A las nueve estaba leyendo."},{"target":"They were watching a movie.","base":"Estaban mirando una película."}]},"takeaways":["Contás qué estaba pasando: I was cooking, they were sleeping.","Preguntás: What were you doing at eight?"]},{"id":"a2-u17-l02","unit_id":"a2-u17","position":2,"title_es":"When y while","objective_es":"Contar una acción que interrumpe otra.","intro":{"explanation":"Cuando una acción corta interrumpe otra larga, la larga va en past continuous y la corta en past simple: I was cooking when the phone rang. While (mientras) va con la acción larga: While I was cooking, the phone rang.","examples":[{"target":"I was sleeping when the phone rang.","base":"Estaba durmiendo cuando sonó el teléfono."},{"target":"While we were walking, we heard a noise.","base":"Mientras caminábamos, oímos un ruido."}]},"takeaways":["Contás una acción que interrumpe otra: I was cooking when the phone rang.","Usás while con la acción larga."]},{"id":"a2-u17-rev1","unit_id":"a2-u17","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Lo que estaba pasando» y «When y while».","intro":null,"takeaways":[]},{"id":"a2-u17-l03","unit_id":"a2-u17","position":4,"title_es":"¿Qué pasó?","objective_es":"Preguntar qué pasó y contar un accidente.","intro":{"explanation":"Para preguntar qué pasó: What happened? Un accidente se cuenta con past simple y past continuous: I fell when I was running. Luckily (por suerte) cuenta lo bueno.","examples":[{"target":"What happened?","base":"¿Qué pasó?"},{"target":"He fell and broke his arm.","base":"Se cayó y se rompió el brazo."}]},"takeaways":["Preguntás What happened? y contás un accidente.","Decís cómo te sentiste: I was scared."]},{"id":"a2-u17-l04","unit_id":"a2-u17","position":5,"title_es":"El orden de la historia","objective_es":"Ordenar un relato: al principio, después, al día siguiente, al final.","intro":{"explanation":"Para ordenar una historia: at first (al principio), then (después), the next day (al día siguiente) e in the end (al final). Para decir que algo empezó: It began to rain (empezó a llover).","examples":[{"target":"At first, I was nervous.","base":"Al principio estaba nervioso."},{"target":"In the end, we were very happy.","base":"Al final estábamos muy contentos."}]},"takeaways":["Ordenás una historia con at first, then, the next day e in the end.","Contás cuándo empezó algo: It began to rain."]},{"id":"a2-u17-rev2","unit_id":"a2-u17","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «¿Qué pasó?» y «El orden de la historia».","intro":null,"takeaways":[]},{"id":"a2-u17-l05","unit_id":"a2-u17","position":7,"title_es":"Tu historia","objective_es":"Contar una historia corta con comienzo, problema y final.","intro":{"explanation":"Una historia corta tiene un comienzo (dónde estabas y qué estabas haciendo), algo que pasó de repente y un final. Usá was/were + -ing para la escena y el past simple para lo que pasó.","examples":[{"target":"I was walking home when I saw an old friend.","base":"Volvía caminando a casa cuando vi a un viejo amigo."},{"target":"In the end, we had dinner together.","base":"Al final, cenamos juntos."}]},"takeaways":["Contás una historia corta con comienzo, problema y final.","Combinás el past continuous y el past simple."]},{"id":"a2-u17-listen","unit_id":"a2-u17","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"a2-u17-words","unit_id":"a2-u17","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"a2-u17-final","unit_id":"a2-u17","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Contar una historia».","intro":null,"takeaways":[]}],"exercises":[{"id":"a2-u13-l01-e01","lesson_id":"a2-u13-l01","position":1,"type":"image_choice","skill":"vocabulary","prompt_es":"¿Qué muestra la imagen?","payload":{"type":"image_choice","emoji":"🐟","options":["fish","meat","soup","salad"]},"answer":"fish","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["en-fish"]},{"id":"a2-u13-l01-e02","lesson_id":"a2-u13-l01","position":2,"type":"image_choice","skill":"vocabulary","prompt_es":"¿Qué muestra la imagen?","payload":{"type":"image_choice","emoji":"🥗","options":["salad","soup","dessert","meat"]},"answer":"salad","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["en-salad"]},{"id":"a2-u13-l01-e03","lesson_id":"a2-u13-l01","position":3,"type":"match_pairs","skill":"vocabulary","prompt_es":"Uní cada palabra con su significado","payload":{"type":"match_pairs","pairs":[{"left":"soup","right":"sopa"},{"left":"meat","right":"carne"},{"left":"vegetables","right":"verduras"},{"left":"dessert","right":"postre"}]},"answer":"","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["en-soup","en-meat","en-vegetables","en-dessert"]},{"id":"a2-u13-l01-e04","lesson_id":"a2-u13-l01","position":4,"type":"fill_blank","skill":"vocabulary","prompt_es":"Completá la frase","payload":{"type":"fill_blank","sentence":"I don't eat meat. I want the ___.","translation":"No como carne. Quiero el pescado.","options":["fish","meat","chicken","milk"]},"answer":"fish","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-fish","en-meat"]},{"id":"a2-u13-l01-e05","lesson_id":"a2-u13-l01","position":5,"type":"listen_choice","skill":"listening","prompt_es":"Escuchá y elegí lo que oís","payload":{"type":"listen_choice","audioText":"Can I see the menu, please?","options":["Can I see the menu, please?","Can I see the map, please?","Can I have the menu, please?","Can we see the menu, please?"]},"answer":"Can I see the menu, please?","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-menu"]},{"id":"a2-u13-l01-e06","lesson_id":"a2-u13-l01","position":6,"type":"order_words","skill":"sentence_building","prompt_es":"Ordená las palabras","payload":{"type":"order_words","tokens":["We","want","soup","and","salad","for","lunch"],"translation":"Queremos sopa y ensalada para el almuerzo."},"answer":"We want soup and salad for lunch.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":25,"words":["en-soup","en-salad"]},{"id":"a2-u13-l01-e07","lesson_id":"a2-u13-l01","position":7,"type":"complete_word","skill":"vocabulary","prompt_es":"Escribí la palabra completa","payload":{"type":"complete_word","masked":"d_ss_rt","hint":"postre"},"answer":"dessert","accepted_answers":[],"explanation_es":"Dessert (postre) lleva doble s. Desert, con una sola, es «desierto».","difficulty":1,"recommended_seconds":20,"words":["en-dessert"]},{"id":"a2-u13-l01-e08","lesson_id":"a2-u13-l01","position":8,"type":"translate_write","skill":"translation","prompt_es":"Traducí al inglés","payload":{"type":"translate_write","source":"Quiero una ensalada."},"answer":"I want a salad.","accepted_answers":["I'd like a salad.","I would like a salad."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["en-salad"]},{"id":"a2-u13-l01-e09","lesson_id":"a2-u13-l01","position":9,"type":"translate_write","skill":"translation","prompt_es":"Traducí al inglés","payload":{"type":"translate_write","source":"No como pescado."},"answer":"I don't eat fish.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["en-fish"]},{"id":"a2-u13-l02-e01","lesson_id":"a2-u13-l02","position":1,"type":"fill_blank","skill":"grammar","prompt_es":"Completá la frase","